 if(q<=a[0][0])return a[0].slice();
 if(q>=a[a.length-1][0])return a[a.length-1].slice();
 let lo=0,hi=a.length-1;while(hi-lo>1){let m=(lo+hi)>>1;if(a[m][0]<q)lo=m;else hi=m;}
